"use strict";
/*
 * PolicyVault v0.7-kas ROOTED KAS SAFE-PAYMENT VAULT (PolicyVaultRootedKas —
 * CANDIDATE generation, NOT byte-frozen) — exact predecessor / successor
 * locking-script reconstruction from the DECLARED template pins and from the
 * vault's own revealed redeem script. Closes R7-04 for this profile with the
 * discipline core/intent/vault-script-v7.js established for the frozen
 * payment profile (Codex checkpoints 6 + 7): the shared deterministic core
 * REBUILDS the script the transaction actually spends and the ONE successor
 * the reviewed state can produce, and binds both to the transaction before
 * any wallet is asked to sign.
 *
 * The candidate covenant (contracts/PolicyVault.v0.7-kas.sil, sha256
 * 393f2130b48d06ba4d5b29ad8846098dd16ae89ebfd658a2df163f0801ac1d8b) compiles, for ANY template + state, to
 *
 *     prefix (1 byte) || STATE REGION (441 bytes) || suffix (template code)
 *
 * where the STATE REGION is silverc's field prolog for the frozen v0.4.1
 * mutable state, in declaration order, each field a fixed-width push:
 *
 *     0x20 boundVaultId[32]  0x08 protectedValue[8 LE]  0x08 feeReserve[8 LE]
 *     0x08 paused[8 LE]      0x20 agentRoot[32]         (0x20 approverN[32]) x 10
 *     0x08 approvalM[8 LE]   0x08 policyNonce[8 LE]
 *
 * and the prefix + suffix are the vault's TEMPLATE, constant across every
 * state of one vault. The suffix is a generation-constant SKELETON with
 * holes: the vault's TEMPLATE CONSTANTS pushed wherever the covenant uses
 * them (scriptLen x6, orgRootCovenantId x10, rootPrefixLen x6, rootSuffixLen x2, rootTemplateVmHash x2, recoveryPk x1) — rootStateLen (467) is fixed by the frozen v0.7 root
 * and folded into the constant chunks; vaultId lives only in the state
 * region. 27 holes, 28 chunks.
 *
 * The skeleton was extracted MECHANICALLY from real silverc output by
 * tools/derive-vault-script-skeleton-v7-kas.js (equal-push-width template
 * triple, token-aligned diff, a shorter fourth compile for the length holes,
 * self-verified byte for byte before emission) and is proven across a state
 * matrix and a constant-encoding template matrix against the real vendored
 * compiler by sdk/test/vault-script-v7-kas-reconstruction.test.js. Pure data
 * + pure functions: runs unchanged in the browser bundle and the mobile
 * vendor copy. No covenant bytes change here; nothing is recompiled.
 *
 * CANDIDATE STATUS: the generation is not byte-frozen. If the covenant source
 * ever changes, this skeleton MUST be re-derived (the reconstruction test and
 * the skeleton sha pin below break first); it is never edited by hand.
 */
const { normalizeStateV4, stateToJsonV4, MAX_APPROVERS } = require("../model/vault-state-v4");
const { normalizeTemplateV7Kas, ROOT_STATE_LEN_V7 } = require("../model/vault-state-v7-kas");
const { pushScriptNumHex, p2shSpkHexOf } = require("./vault-script-v7");

/* silverc's state_layout for the v0.7-kas candidate generation (start = the
 * 1-byte selector prefix, len = 33 + 9 + 9 + 9 + 33 + 10 x 33 + 9 + 9). */
const VAULT_SCRIPT_PREFIX_LEN_V7_KAS = 1;
const VAULT_STATE_REGION_LEN_V7_KAS = 441;
const HEX64 = /^[0-9a-f]{64}$/;

/* ---- the v0.7-kas CANDIDATE template skeleton (mechanically derived) ---- */
const VAULT_SCRIPT_PREFIX_HEX_V7_KAS = "6b";
const VAULT_SCRIPT_HOLES_V7_KAS = Object.freeze(["scriptLen","scriptLen","orgRootCovenantId","orgRootCovenantId","orgRootCovenantId","rootPrefixLen","rootSuffixLen","rootPrefixLen","rootPrefixLen","rootTemplateVmHash","orgRootCovenantId","orgRootCovenantId","scriptLen","scriptLen","orgRootCovenantId","orgRootCovenantId","orgRootCovenantId","rootPrefixLen","rootSuffixLen","rootPrefixLen","rootPrefixLen","rootTemplateVmHash","orgRootCovenantId","orgRootCovenantId","recoveryPk","scriptLen","scriptLen"]);
/* generation-constant suffix chunks between the holes (hex), extracted from real silverc output of the candidate v0.7-kas covenant */
const VAULT_SCRIPT_CHUNKS_V7_KAS = Object.freeze([
  "",
  "94765193bc7c7eb976c976",
  "",
  "d0519c69",
  "d2519c69",
  "00d176c97878",
  "02d30193",
  "93945279bc5279bf78aa02000001aa7e01207e7c7e01877e876976",
  "007c7f7882",
  "7c7f7602d3015b94007c7f788202d3015b947c7f765b007c7f78825b7c7f5579787eaa",
  "87697852007c7f527982527c7f7802010087697651007c7f7882517c7f7801088769",
  "00d3c35a7959797e5f7901087e5379519358cd7e7e56797eaa02000001aa7e01207e7c7e01877e8769b37651a2697658a169",
  "",
  "94765193bc7c7eb976c976",
  "",
  "d0519c69",
  "d2519c69",
  "00d176c97878",
  "02d30193",
  "93945279bc5279bf78aa02000001aa7e01207e7c7e01877e876976",
  "007c7f7882",
  "7c7f7602d3015b94007c7f788202d3015b947c7f765b007c7f78825b7c7f5579787eaa",
  "87697852007c7f527982527c7f7802010087697651007c7f7882517c7f7801088769",
  "00d3c35a7959797e02010001087e5379519358cd7e7e56797eaa02000001aa7e01207e7c7e01877e8769b37651a2697658a169",
  "",
  "",
  "94765193bc7c7eb976c976",
  "9402ba01937cbc7eaa02000001aa7e01207e7c7e01877eb95279ccc387697651937b757768007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75007a75757575757575757575757575757575757575757575757575757575757575757575755167750069686868",
]);
const VAULT_SCRIPT_SKELETON_SHA256_V7_KAS = "13709e50585d8d77a95eb3c981045bb153ec95c08d8ba837acc21b8d1f4d1904"; // sha256(chunks.join("|") + "#" + holes.join(","))
const VAULT_SCRIPT_COVENANT_SOURCE_SHA256_V7_KAS = "393f2130b48d06ba4d5b29ad8846098dd16ae89ebfd658a2df163f0801ac1d8b"; // the CANDIDATE source the skeleton was derived from

const VAULT_SCRIPT_PIN_HOLES_V7_KAS = Object.freeze(["orgRootCovenantId", "rootTemplateVmHash", "rootPrefixLen", "rootSuffixLen", "recoveryPk"]);
const VAULT_SCRIPT_INT_HOLES_V7_KAS = new Set(["rootPrefixLen", "rootSuffixLen"]);

function fail(message, code) {
  const e = new Error(`vault-script-v7-kas: ${message}`);
  e.code = code || "VAULT_SCRIPT_INVALID";
  throw e;
}
function le8Hex(value, field) {
  const v = BigInt(value);
  if (v < 0n || v > 0xffffffffffffffffn) fail(`${field} outside the 8-byte domain`);
  let out = "";
  let x = v;
  for (let i = 0; i < 8; i++) { out += Number(x & 0xffn).toString(16).padStart(2, "0"); x >>= 8n; }
  return out;
}
function hex64(value, field) {
  const h = String(value || "").toLowerCase();
  if (!HEX64.test(h)) fail(`${field} must be 32 bytes of hex`);
  return h;
}
/* Accept the model's NORMALIZED state (BigInt fields, 10 approver slots) or
 * its JSON / raw input shape; both go through the shared v4 normalizer. */
function normalizeStateInput(state) {
  if (!state || typeof state !== "object") fail("state object is required");
  return normalizeStateV4(typeof state.protectedValue === "bigint" ? stateToJsonV4(state) : state);
}

/* The exact 441-byte state region (hex) for a vault id + mutable state. */
function serializeVaultStateRegionHexV7Kas({ vaultId, state }) {
  const s = normalizeStateInput(state);
  let out = "20" + hex64(vaultId, "vaultId") + "08" + le8Hex(s.protectedValue, "protectedValue") + "08" + le8Hex(s.feeReserve, "feeReserve") + "08" + le8Hex(s.paused, "paused") + "20" + s.agentRoot;
  for (let i = 0; i < MAX_APPROVERS; i++) out += "20" + s.approvers[i];
  return out + "08" + le8Hex(s.approvalM, "approvalM") + "08" + le8Hex(s.policyNonce, "policyNonce");
}

/* Strict inverse: decode a 441-byte region (hex) or fail closed. The state
 * comes back in the stateToJsonV4 shape (decimal strings, approverSlots). */
function parseVaultStateRegionHexV7Kas(regionHex) {
  const r = String(regionHex || "").toLowerCase();
  if (!/^[0-9a-f]+$/.test(r) || r.length !== VAULT_STATE_REGION_LEN_V7_KAS * 2) fail("state region must be exactly 441 bytes of hex");
  let p = 0;
  const take = (n) => { const out = r.slice(p, p + n * 2); p += n * 2; return out; };
  const opcode = (expected, what) => { if (take(1) !== expected) fail(`${what}: unexpected push opcode`); };
  const le8 = () => { const h = take(8); let v = 0n; for (let i = 7; i >= 0; i--) v = (v << 8n) | BigInt(parseInt(h.substr(i * 2, 2), 16)); return v; };
  opcode("20", "boundVaultId"); const vaultId = take(32);
  opcode("08", "protectedValue"); const protectedValue = le8();
  opcode("08", "feeReserve"); const feeReserve = le8();
  opcode("08", "paused"); const paused = le8();
  opcode("20", "agentRoot"); const agentRoot = take(32);
  const approverSlots = [];
  for (let i = 0; i < MAX_APPROVERS; i++) { opcode("20", `approver${i + 1}`); approverSlots.push(take(32)); }
  opcode("08", "approvalM"); const approvalM = le8();
  opcode("08", "policyNonce"); const policyNonce = le8();
  return Object.freeze({
    vaultId,
    state: Object.freeze({ protectedValue: protectedValue.toString(), feeReserve: feeReserve.toString(), paused: paused.toString(), agentRoot, approverSlots: Object.freeze(approverSlots), approvalM: approvalM.toString(), policyNonce: policyNonce.toString() })
  });
}

/* Split a revealed v0.7-kas redeem script into prefix / region / suffix. */
function splitVaultRedeemHexV7Kas(redeemHex) {
  const h = String(redeemHex || "").toLowerCase();
  if (!/^[0-9a-f]+$/.test(h) || h.length % 2 !== 0) fail("redeem script must be hex", "VAULT_SCRIPT_INVALID");
  const minLen = VAULT_SCRIPT_PREFIX_LEN_V7_KAS + VAULT_STATE_REGION_LEN_V7_KAS + 1;
  if (h.length / 2 < minLen) fail("redeem script is shorter than prefix + state region + suffix", "VAULT_SCRIPT_INVALID");
  const prefixHex = h.slice(0, VAULT_SCRIPT_PREFIX_LEN_V7_KAS * 2);
  const regionHex = h.slice(VAULT_SCRIPT_PREFIX_LEN_V7_KAS * 2, (VAULT_SCRIPT_PREFIX_LEN_V7_KAS + VAULT_STATE_REGION_LEN_V7_KAS) * 2);
  const suffixHex = h.slice((VAULT_SCRIPT_PREFIX_LEN_V7_KAS + VAULT_STATE_REGION_LEN_V7_KAS) * 2);
  return Object.freeze({ prefixHex, regionHex, suffixHex, decoded: parseVaultStateRegionHexV7Kas(regionHex) });
}

/* The successor redeem script: the predecessor's template around the successor state. */
function reconstructVaultSuccessorHexV7Kas({ redeemHex, vaultId, state }) {
  const parts = splitVaultRedeemHexV7Kas(redeemHex);
  return parts.prefixHex + serializeVaultStateRegionHexV7Kas({ vaultId, state }) + parts.suffixHex;
}
function reconstructVaultSuccessorSpkHexV7Kas(args) { return p2shSpkHexOf(reconstructVaultSuccessorHexV7Kas(args)); }

/*
 * The exact v0.7-kas SUFFIX (template code) for a set of template pins.
 * `template` is normalized by the model (well-formed pins only; rootStateLen
 * must be the frozen root's 467, which the skeleton folds as a constant). The
 * script's own length is pushed inside the suffix, so the length is solved as
 * a fixed point (the push width can change the length it encodes).
 */
function reconstructVaultSuffixHexV7Kas(template) {
  const t = normalizeTemplateV7Kas(template);
  if (Number(t.rootStateLen) !== ROOT_STATE_LEN_V7) fail(`rootStateLen ${t.rootStateLen} is not the frozen root layout the skeleton folds (${ROOT_STATE_LEN_V7})`);
  const constants = {};
  for (const name of VAULT_SCRIPT_PIN_HOLES_V7_KAS) constants[name] = VAULT_SCRIPT_INT_HOLES_V7_KAS.has(name) ? pushScriptNumHex(t[name]) : "20" + hex64(t[name], name);
  const assemble = (lenPush) => {
    let out = "";
    for (let i = 0; i < VAULT_SCRIPT_HOLES_V7_KAS.length; i++) {
      out += VAULT_SCRIPT_CHUNKS_V7_KAS[i];
      const h = VAULT_SCRIPT_HOLES_V7_KAS[i];
      out += h === "scriptLen" ? lenPush : constants[h];
    }
    return out + VAULT_SCRIPT_CHUNKS_V7_KAS[VAULT_SCRIPT_CHUNKS_V7_KAS.length - 1];
  };
  let lenPush = pushScriptNumHex(VAULT_SCRIPT_PREFIX_LEN_V7_KAS + VAULT_STATE_REGION_LEN_V7_KAS + assemble("020000").length / 2);
  for (let round = 0; round < 4; round++) {
    const suffix = assemble(lenPush);
    const next = pushScriptNumHex(VAULT_SCRIPT_PREFIX_LEN_V7_KAS + VAULT_STATE_REGION_LEN_V7_KAS + suffix.length / 2);
    if (next === lenPush) return suffix;
    lenPush = next;
  }
  return fail("the script length did not converge");
}

/* The exact redeem script (hex) for template pins + a vault state:
 * prefix || region(vaultId, state) || suffix(pins). */
function reconstructVaultScriptHexV7Kas({ template, state }) {
  const t = normalizeTemplateV7Kas(template);
  return VAULT_SCRIPT_PREFIX_HEX_V7_KAS + serializeVaultStateRegionHexV7Kas({ vaultId: t.vaultId, state }) + reconstructVaultSuffixHexV7Kas(t);
}
function reconstructVaultScriptSpkHexV7Kas(args) { return p2shSpkHexOf(reconstructVaultScriptHexV7Kas(args)); }

/*
 * Read the template pins OUT OF a revealed redeem script by walking the
 * skeleton: every constant chunk must appear verbatim at its place and every
 * hole must hold a well-formed push of the expected kind; all holes of one
 * constant must agree and the six length holes must be the script's own
 * length. Returns { vaultId, state, pins } or throws VAULT_GENERATION_MISMATCH
 * — so a script of ANOTHER generation (the frozen v0.7-payment vault, an HD
 * candidate, a foreign covenant) is never mistaken for a v0.7-kas vault, and
 * a v0.7-kas vault can never be presented under another generation label.
 */
function decodeVaultTemplatePinsV7Kas(redeemHex) {
  const parts = splitVaultRedeemHexV7Kas(redeemHex);
  const s = parts.suffixHex;
  let p = 0;
  const holes = {}; // decoded hole contents (root geometry lengths + 32-byte pins) — NOT amounts
  const readIntPush = (what) => {
    const op = parseInt(s.slice(p, p + 2), 16);
    if (Number.isNaN(op)) fail(`${what}: truncated push`, "VAULT_GENERATION_MISMATCH");
    if (op === 0x00) { p += 2; return 0n; }
    if (op >= 0x51 && op <= 0x60) { p += 2; return BigInt(op - 0x50); }
    if (op >= 0x01 && op <= 0x4b) {
      const data = s.slice(p + 2, p + 2 + op * 2);
      if (data.length !== op * 2) fail(`${what}: truncated push`, "VAULT_GENERATION_MISMATCH");
      let v = 0n;
      for (let i = op - 1; i >= 0; i--) v = (v << 8n) | BigInt(parseInt(data.substr(i * 2, 2), 16));
      if (pushScriptNumHex(v) !== s.slice(p, p + 2 + op * 2)) fail(`${what}: non-minimal integer push`, "VAULT_GENERATION_MISMATCH");
      p += 2 + op * 2;
      return v;
    }
    return fail(`${what}: not an integer push`, "VAULT_GENERATION_MISMATCH");
  };
  const readBytes32Push = (what) => {
    if (s.slice(p, p + 2) !== "20") fail(`${what}: not a 32-byte push`, "VAULT_GENERATION_MISMATCH");
    const v = s.slice(p + 2, p + 66);
    if (!HEX64.test(v)) fail(`${what}: truncated 32-byte push`, "VAULT_GENERATION_MISMATCH");
    p += 66;
    return v;
  };
  for (let i = 0; i < VAULT_SCRIPT_HOLES_V7_KAS.length; i++) {
    const chunk = VAULT_SCRIPT_CHUNKS_V7_KAS[i];
    if (s.slice(p, p + chunk.length) !== chunk) fail(`the script is not the candidate v0.7-kas generation (chunk ${i} differs)`, "VAULT_GENERATION_MISMATCH");
    p += chunk.length;
    const h = VAULT_SCRIPT_HOLES_V7_KAS[i];
    const v = h === "scriptLen" || VAULT_SCRIPT_INT_HOLES_V7_KAS.has(h) ? readIntPush(h) : readBytes32Push(h);
    if (Object.prototype.hasOwnProperty.call(holes, h)) { if (holes[h] !== v) fail(`the script's ${h} constants disagree`, "VAULT_GENERATION_MISMATCH"); } else holes[h] = v;
  }
  const last = VAULT_SCRIPT_CHUNKS_V7_KAS[VAULT_SCRIPT_CHUNKS_V7_KAS.length - 1];
  if (s.slice(p) !== last) fail("the script is not the candidate v0.7-kas generation (tail differs)", "VAULT_GENERATION_MISMATCH");
  if (holes.scriptLen !== BigInt(String(redeemHex).length / 2)) fail("the script's own length constant is not its length", "VAULT_GENERATION_MISMATCH");
  const pins = {
    vaultId: parts.decoded.vaultId,
    orgRootCovenantId: holes.orgRootCovenantId,
    rootTemplateVmHash: holes.rootTemplateVmHash,
    rootPrefixLen: Number(holes.rootPrefixLen),
    rootStateLen: ROOT_STATE_LEN_V7,
    rootSuffixLen: Number(holes.rootSuffixLen),
    recoveryPk: holes.recoveryPk
  };
  return Object.freeze({ vaultId: parts.decoded.vaultId, state: parts.decoded.state, pins: Object.freeze(pins) });
}
function isKasGenerationScriptV7(redeemHex) {
  try { decodeVaultTemplatePinsV7Kas(redeemHex); return true; } catch { return false; }
}

/* The template pins a rooted-KAS-vault manifest declares, in the model's
 * shape (the verifier hands its declared `vault` block here; nothing is
 * trusted until the rebuilt script is the one the transaction spends). */
function templatePinsFromManifestVaultV7Kas(vault) {
  const g = vault && vault.rootGeometry && typeof vault.rootGeometry === "object" ? vault.rootGeometry : {};
  return {
    vaultId: vault ? vault.vaultId : undefined,
    orgRootCovenantId: vault ? vault.orgRootCovenantId : undefined,
    rootTemplateVmHash: vault ? vault.rootTemplateVmHash : undefined,
    rootPrefixLen: g.prefixLen,
    rootStateLen: g.stateLen,
    rootSuffixLen: g.suffixLen,
    recoveryPk: vault ? vault.recoveryPk : undefined
  };
}

module.exports = Object.freeze({
  VAULT_SCRIPT_PREFIX_LEN_V7_KAS,
  VAULT_STATE_REGION_LEN_V7_KAS,
  VAULT_SCRIPT_PREFIX_HEX_V7_KAS,
  VAULT_SCRIPT_HOLES_V7_KAS,
  VAULT_SCRIPT_CHUNKS_V7_KAS,
  VAULT_SCRIPT_SKELETON_SHA256_V7_KAS,
  VAULT_SCRIPT_COVENANT_SOURCE_SHA256_V7_KAS,
  VAULT_SCRIPT_PIN_HOLES_V7_KAS,
  serializeVaultStateRegionHexV7Kas,
  parseVaultStateRegionHexV7Kas,
  splitVaultRedeemHexV7Kas,
  p2shSpkHexOf,
  reconstructVaultSuccessorHexV7Kas,
  reconstructVaultSuccessorSpkHexV7Kas,
  reconstructVaultSuffixHexV7Kas,
  reconstructVaultScriptHexV7Kas,
  reconstructVaultScriptSpkHexV7Kas,
  decodeVaultTemplatePinsV7Kas,
  isKasGenerationScriptV7,
  templatePinsFromManifestVaultV7Kas
});
